const inputJson = $('When Executed by Another Workflow').first().json;

if (!inputJson.callback_query || !inputJson.callback_query.data) {
    throw new Error("لم يتم العثور على بيانات الزر في العقدة الأولى.");
}

const rawData = inputJson.callback_query.data;
const parts = rawData.split('__');

const actionName = parts[0];

return {
    json: {
        action: actionName,
        record_type: parts[1] || "",
        row_id: parts[2] || parts[1] || "",
        habit_id: (actionName === 'done_habit' || actionName === 'snooze') ? parts[1] : "",
        task_id: (actionName === 'done_task') ? parts[1] : "",
        raw_data: rawData
    }
};

const habit = $input.first().json;
const now = new Date();
const today = now.toISOString().split('T')[0];

const yesterdayDate = new Date(now);
yesterdayDate.setDate(yesterdayDate.getDate() - 1);
const yesterday = yesterdayDate.toISOString().split('T')[0];

let currentStreak = Number(habit.current_streak) || 0;
let bestStreak = Number(habit.best_streak) || 0;
let alreadyDone = false;

if (habit.last_completed_date === today) {
    alreadyDone = true;
} else if (habit.last_completed_date === yesterday) {
    currentStreak += 1;
} else {
    currentStreak = 1;
}

if (currentStreak > bestStreak) {
    bestStreak = currentStreak;
}

const targetMin = Number(habit.target_minutes) || 15;
const totalMinutes = currentStreak * targetMin;

return [{
    json: {
        row_number: habit.row_number,
        habit_id: habit.habit_id,
        habit_name: habit.habit_name,
        target_minutes: targetMin,
        current_streak: currentStreak,
        best_streak: bestStreak,
        last_completed_date: today,
        snooze_until: "",
        already_done: alreadyDone,
        total_minutes: totalMinutes,
        inserted_by: habit.inserted_by || "User"
    }
}];

const habit = $input.first().json;
const now = new Date();
const currentHour = (now.getUTCHours() + 3) % 24;
const nextHour = (currentHour + 1) % 24;
const snoozeStr = `${String(nextHour).padStart(2, '0')}:00`;

return [{
    json: {
        row_number: habit.row_number,
        habit_id: habit.habit_id,
        habit_name: habit.habit_name,
        snooze_until: snoozeStr
    }
}];
